DO $$ DECLARE n int; BEGIN SELECT count(*) INTO n FROM public.profiles WHERE email LIKE 'sahne+%'; IF n <> 171 THEN RAISE EXCEPTION 'profil sayisi % (beklenen 171) — handle_new_user?', n; END IF; END $$;

-- Sahne yoneticisi (admin paneli icin); koruma tetikleyicisi gecici kapatilir (asama4 T5 kalibi)

ALTER TABLE public.profiles DISABLE TRIGGER protect_profile_fields;
UPDATE public.profiles SET is_admin = true WHERE id = '5a4e0000-0000-4000-8000-000000090001';
ALTER TABLE public.profiles ENABLE TRIGGER protect_profile_fields;

-- profil alanlari (onay alanlari icin auth.uid() = Sahne yoneticisi)

DO $$
BEGIN
  PERFORM set_config('request.jwt.claim.sub', '5a4e0000-0000-4000-8000-000000090001', true);
  UPDATE public.profiles p SET
    slug = v.slug, bio = v.bio, city_id = pg_temp.sehir(v.sehir), primary_category_id = pg_temp.kat(v.kat),
    attributes = v.attrs, category_attributes = v.cat_attrs, approval_status = v.onay::public.profile_approval_status,
    approved_at = v.onay_at, approval_note = v.onay_not, suspended_at = v.askida_at, suspension_reason = v.askida_neden,
    suspended_by = CASE WHEN v.askida_at IS NULL THEN NULL ELSE '5a4e0000-0000-4000-8000-000000090001'::uuid END,
    is_published = v.yayinda, premium_tier = v.premium::public.premium_tier, premium_until = v.premium_until,
    last_seen_at = v.son_gorulme, created_at = v.kayit, welcome_email_sent_at = v.kayit
  FROM (VALUES
('5a4e0000-0000-4000-8000-000000010001', 'eda-bozkurt', 'Düğün ve kurumsal etkinlik fotoğrafçılığında 3 yıllık deneyim. İzmir ve çevre illerde çalışıyorum; düğün ve aile ağırlıklı portföyüm var. İkinci fotoğrafçı ve drone desteği sağlayabilirim.', 'İzmir', 'fotografci', '{"shoot_types": ["portrait", "newborn", "wedding", "product"], "style": ["vintage", "minimal", "artistic", "classic"], "extras": ["studio", "drone", "makeup", "album"], "delivery_format": ["digital", "album", "print", "online"], "team_type": "both", "delivery_time": "normal", "experience": "mid"}'::jsonb, '{}'::jsonb, 'approved', pg_temp.t(7366.40), NULL, NULL, NULL, true, 'premium', pg_temp.t(-1704.00), pg_temp.t(115.55), pg_temp.t(7425.21)),
('5a4e0000-0000-4000-8000-000000010002', 'berk-polat', '9 yıldır Muğla merkezli çalışan bir etkinlik fotoğrafçısıyım. lansman ve gala çekimlerinde doğal ışık ve anı yakalamaya odaklanırım. Teslimatı 10 gün içinde online galeriyle yaparım.', 'Muğla', 'fotografci', '{"shoot_types": ["social", "portrait", "architecture", "newborn"], "style": ["artistic", "vintage"], "extras": ["sameday", "drone", "makeup", "studio"], "delivery_format": ["print", "digital", "album", "online"], "team_type": "team", "delivery_time": "standard", "experience": "senior"}'::jsonb, '{}'::jsonb, 'approved', pg_temp.t(3271.82), NULL, NULL, NULL, true, 'none', NULL, pg_temp.t(479.84), pg_temp.t(3293.15)),
('5a4e0000-0000-4000-8000-000000010003', 'kerem-oz', 'Düğün ve kurumsal etkinlik fotoğrafçılığında 10 yıllık deneyim. İstanbul ve çevre illerde çalışıyorum; lansman ve gala ağırlıklı portföyüm var. İkinci fotoğrafçı ve drone desteği sağlayabilirim.', 'İstanbul', 'fotografci', '{"shoot_types": ["wedding", "food", "event", "product"], "style": ["minimal", "artistic"], "extras": ["album"], "delivery_format": ["print"], "team_type": "solo", "delivery_time": "fast", "experience": "expert"}'::jsonb, '{}'::jsonb, 'approved', pg_temp.t(2411.03), NULL, NULL, NULL, true, 'none', NULL, pg_temp.t(407.02), pg_temp.t(2444.47)),
('5a4e0000-0000-4000-8000-000000010004', 'burcu-ates', '12 yıldır İstanbul merkezli çalışan bir etkinlik fotoğrafçısıyım. düğün ve aile çekimlerinde doğal ışık ve anı yakalamaya odaklanırım. Teslimatı 10 gün içinde online galeriyle yaparım.', 'İstanbul', 'fotografci', '{"shoot_types": ["portrait", "product", "sports", "corporate"], "style": ["minimal", "vintage"], "extras": ["studio"], "delivery_format": ["digital"], "team_type": "solo", "delivery_time": "standard", "experience": "expert"}'::jsonb, '{}'::jsonb, 'approved', pg_temp.t(6900.28), NULL, NULL, NULL, true, 'none', NULL, pg_temp.t(440.08), pg_temp.t(6917.83)),
