('5a4e0000-0000-4000-8000-000000010122', 'selim-dogan', 'Trabzon merkezli lisanslı drone pilotuyum. 7 yıldır konser ve festival çekimleri yapıyorum; uçuş izinlerini ben alırım, 4K video ve yüksek çözünürlüklü fotoğraf teslim ederim. Kurgu ve renk dahil paketlerim var.', 'Trabzon', 'drone-pilotu', '{}'::jsonb, '{"service_region": "Yalnızca kendi şehri", "experience_label": "7 yıl · 133+ etkinlik", "calisma_sekli": "Freelance + Ajansa bağlı", "quick": {"drone_tipi": ["Standart drone"], "lokasyon_tipi": ["Açık alan", "Kıyı ve su"], "teslim_bicimi": "Video", "teslim_suresi": "1–3 gün"}, "logistics": {"ucus_izni": true, "kendi_ekipmani": true}, "modules": {"ekipman": {"items": ["DJI Mavic 3 Pro", "DJI Avata 2 (FPV)", "Yedek batarya x6", "ND filtre seti"], "venue_requirements": "Sahne yakınında 2 adet 16A priz, kurulum için 60 dk."}, "teknik_teslimat": {"delivery": {"Teslim süresi": "1–3 gün", "Format": "4K + 1080p", "Yedekleme": "Çift kart + bulut"}}, "uzmanlik_alanlari": {"areas": ["Spor / Aksiyon Çekimi", "Drone Fotoğrafçısı", "Outdoor Etkinlik Çekimi", "Düğün Drone Çekimi"]}, "calisma_parametreleri": {"params": {"Minimum süre": "Tam gün", "Şehir dışı": "Türkiye geneli, ulaşım dahil", "Ödeme": "%30 kapora, kalan etkinlik günü"}, "notes": "Hafta sonu ve resmi tatil için önceden rezervasyon önerilir."}}}'::jsonb, 'approved', pg_temp.t(7393.80), NULL, NULL, NULL, true, 'none', NULL, pg_temp.t(218.76), pg_temp.t(7437.59)),
('5a4e0000-0000-4000-8000-000000020001', 'ajans-nova', 'Nova Etkinlik, 2014''ten beri İstanbul''da düğün, nişan ve kurumsal etkinlik organizasyonu yapan tam kapsamlı bir ajanstır. Konsept tasarımı, tedarikçi yönetimi ve etkinlik günü operasyonunu tek ekipten yürütür; 60''ın üzerinde düzenli freelance iş ortağıyla çalışır.', 'İstanbul', 'organizasyon', '{}'::jsonb, '{"service_region": "Türkiye geneli", "experience_label": "6 yıl · 360+ etkinlik"}'::jsonb, 'approved', pg_temp.t(5312.21), NULL, NULL, NULL, true, 'agency', pg_temp.t(-3072.00), pg_temp.t(8.97), pg_temp.t(5342.69)),
('5a4e0000-0000-4000-8000-000000020002', 'ajans-lumen', 'Lumen Prodüksiyon konser, konferans ve lansmanlarda ses, ışık, LED ekran ve canlı yayın altyapısını kurar. 2.000 kişiye kadar sahne çözümleri, çok kameralı reji ve hibrit yayın hizmetini kendi ekipmanıyla sunar.', 'İstanbul', 'ses-isik', '{}'::jsonb, '{"service_region": "Türkiye geneli", "experience_label": "6 yıl · 360+ etkinlik"}'::jsonb, 'approved', pg_temp.t(5116.21), NULL, NULL, NULL, true, 'plus', pg_temp.t(-1608.00), pg_temp.t(26.44), pg_temp.t(5181.47)),
('5a4e0000-0000-4000-8000-000000020003', 'ajans-atlas', 'Ankara merkezli Atlas Organizasyon, kamu ve özel sektör için kongre, bayi toplantısı ve protokol etkinlikleri düzenler. Kayıt sistemi, simultane çeviri ve sahne prodüksiyonu dahil anahtar teslim çözüm sunar.', 'Ankara', 'organizasyon', '{}'::jsonb, '{"service_region": "Türkiye geneli", "experience_label": "8 yıl · 480+ etkinlik"}'::jsonb, 'approved', pg_temp.t(5441.46), NULL, NULL, NULL, true, 'none', NULL, pg_temp.t(26.55), pg_temp.t(5481.34)),
('5a4e0000-0000-4000-8000-000000020004', 'ajans-kuzey-yildizi', 'İzmir ve Ege kıyılarında butik düğün ve kına organizasyonları. Kuzey Yıldızı Events, Çeşme, Alaçatı ve Urla''daki mekan ağıyla açık hava davetleri planlar; dekorasyon ve çiçek tasarımı ekibi kendisine aittir.', 'İzmir', 'organizasyon', '{}'::jsonb, '{"service_region": "Türkiye geneli", "experience_label": "6 yıl · 360+ etkinlik"}'::jsonb, 'approved', pg_temp.t(7549.04), NULL, NULL, NULL, true, 'none', NULL, pg_temp.t(144.48), pg_temp.t(7566.14)),
('5a4e0000-0000-4000-8000-000000020005', 'ajans-mavi-sahne', 'Mavi Sahne, sahne sanatçıları temsil eden bir müzik ve performans ajansıdır. Orkestra, DJ, dans ve akrobasi ekipleriyle düğün, gala ve festival programlarına sanatçı sağlar; ses ve ışık ortaklarıyla paket teklif verir.', 'İstanbul', 'muzisyen', '{}'::jsonb, '{"service_region": "Türkiye geneli", "experience_label": "10 yıl · 600+ etkinlik"}'::jsonb, 'approved', pg_temp.t(7947.96), NULL, NULL, NULL, true, 'agency', pg_temp.t(-3120.00), pg_temp.t(32.41), pg_temp.t(7976.45)),
('5a4e0000-0000-4000-8000-000000020006', 'ajans-arti-bir', 'Artı Bir Ajans sunucu, konuşmacı ve komedyen portföyüyle kurumsal etkinliklerin sahne akışını kurar. Bayi toplantısı, ödül töreni ve lansmanlar için iki dilli sunucu ve ara performans sağlar.', 'İstanbul', 'sunucu', '{}'::jsonb, '{"service_region": "Türkiye geneli", "experience_label": "8 yıl · 480+ etkinlik"}'::jsonb, 'approved', pg_temp.t(10615.56), NULL, NULL, NULL, true, 'none', NULL, pg_temp.t(27.76), pg_temp.t(10651.30)),
('5a4e0000-0000-4000-8000-000000020007', 'ajans-ritim', 'Antalya merkezli Ritim Müzik Ajansı otel ve beach club etkinliklerine DJ, canlı müzik ve dans ekipleri sağlar. Sezonluk rezidans programları ve düğün paketleriyle Akdeniz bölgesinde çalışır.', 'Antalya', 'dj', '{}'::jsonb, '{"service_region": "Türkiye geneli", "experience_label": "14 yıl · 840+ etkinlik"}'::jsonb, 'approved', pg_temp.t(9391.88), NULL, NULL, NULL, true, 'none', NULL, pg_temp.t(117.60), pg_temp.t(9412.34)),
('5a4e0000-0000-4000-8000-000000020008', 'ajans-vizyon-cast', 'Vizyon Cast Ajansı reklam, katalog ve etkinlikler için model, oyuncu ve host kadrosu sağlar. 200''ü aşkın portföy, seçme (casting) organizasyonu ve set günü koordinasyonu hizmetleriyle marka ve prodüksiyon şirketleriyle çalışır.', 'İstanbul', 'model', '{}'::jsonb, '{"service_region": "Türkiye geneli", "experience_label": "12 yıl · 720+ etkinlik"}'::jsonb, 'approved', pg_temp.t(4718.88), NULL, NULL, NULL, true, 'plus', pg_temp.t(-5808.00), pg_temp.t(86.62), pg_temp.t(4770.60)),
('5a4e0000-0000-4000-8000-000000020009', 'ajans-pusula', 'Bursa merkezli Pusula Etkinlik sanayi kuruluşlarının bayi toplantısı, fabrika açılışı ve fuar katılımlarını planlar. Saha koordinasyon ekibi, hostes kadrosu ve teknik tedarikçi ağıyla Marmara bölgesinde hizmet verir.', 'Bursa', 'etkinlik-koordinatoru', '{}'::jsonb, '{"service_region": "Türkiye geneli", "experience_label": "10 yıl · 600+ etkinlik"}'::jsonb, 'approved', pg_temp.t(9254.02), NULL, NULL, NULL, true, 'none', NULL, pg_temp.t(34.11), pg_temp.t(9266.00)),
('5a4e0000-0000-4000-8000-000000020010', 'ajans-ekim', 'Ekim Kreatif, lansman ve marka etkinliklerinin sosyal medya katmanını yönetir: içerik üreticisi eşleştirme, etkinlik günü çekim ekibi, canlı yayın ve aynı gün kurgu. Veriye dayalı raporlama sunar.', 'İstanbul', 'influencer', '{}'::jsonb, '{"service_region": "Türkiye geneli", "experience_label": "14 yıl · 840+ etkinlik"}'::jsonb, 'approved', pg_temp.t(11591.61), NULL, NULL, NULL, true, 'none', NULL, pg_temp.t(61.60), pg_temp.t(11640.12)),
('5a4e0000-0000-4000-8000-000000020011', 'ajans-beyaz-guvercin', 'Gaziantep ve Güneydoğu''da düğün, kına ve sünnet organizasyonları. Beyaz Güvercin, yöresel müzik ekipleri, geleneksel kına programı ve çocuk eğlencesi dahil aile etkinliklerinde 12 yıllık deneyime sahiptir.', 'Gaziantep', 'organizasyon', '{}'::jsonb, '{"service_region": "Türkiye geneli", "experience_label": "10 yıl · 600+ etkinlik"}'::jsonb, 'approved', pg_temp.t(2407.25), NULL, NULL, NULL, true, 'none', NULL, pg_temp.t(55.00), pg_temp.t(2456.08)),
